-- Summer Camp Quests: 5 scenarios + 60 characters (plan 2026-10-26)
insert into public.game_scenarios (id, game, seq, title, inspiration, story, setting, stages, class_plan, asset_ids,
  rounds, minutes_per_round, character_count, active, plan_version)
select e->>0, 'summer_camp', (e->>1)::smallint, e->>2, e->>3, e->>4, e->>5, e->6, e->7,
  array(select jsonb_array_elements_text(e->8)), 6, 5, 12, true, 2
from jsonb_array_elements($j$[["camp-01",1,"Ngày Đầu Trại Hè Bên Hồ","File mục II.1 (dựng lều, nhóm lửa, nướng thịt, lọc nước) + video trại bên hồ, cờ tam giác, chảo trên bếp đá vòng.","Chiếc xe buýt trại hè dừng bên hồ Ngọc, anh Trưởng trại Phong giao cho mỗi Đội Lều một khoảng đất trống và một tấm Bảng Nhiệm vụ còn trắng tinh. Trước khi mặt trời lặn, cả trại phải có lều vững, lửa ấm, bữa tối nướng thơm và nước sạch cho đêm đầu tiên. Mỗi công cụ (búa cọc, đá đánh lửa, vỉ nướng, bình lọc) bị khóa trong rương gỗ, và chỉ mở khi cả đội trả lời đúng. Đúng lúc bếp vừa đỏ lửa thì một đàn sóc tinh nghịch tha mất túi xúc xích, kéo cả trại vào cuộc truy tìm nho nhỏ. Khi trăng lên, nếu Bảng Nhiệm vụ đầy sao, lửa trại sẽ bùng lên thành hình lá cờ của đội giỏi nhất.","Bãi cỏ bên hồ xanh ngọc dưới chân núi, nắng sớm xuyên kẽ lá thông, cờ tam giác nhiều màu căng giữa hai cây. Gió mát, mặt hồ lấp lánh, tiếng chim gõ kiến. Từ đồi cao nhìn xuống thấy cả khu trại nhỏ: nhà gỗ, nhà trên cây, bếp lửa; cô hướng dẫn viên đeo ba lô đứng chờ ở cổng.",[{"n":1,"title":"Đến trại và mở rương","minutes":5,"optional":false,"goal":"Nhận đất cắm trại, mở rương công cụ đầu tiên.","beats":["Phim ngắn: xe buýt dừng bên hồ, anh Phong phát Bảng Nhiệm vụ.","Mỗi Đội Lều mở rương gỗ bằng 3 câu đúng.","Cô hướng dẫn mở bản đồ nổi của trại; mỗi nơi chạm đúng tên là sáng lên.","Đống đồ trại bên cạnh rương: gọi đúng tên từng món thì Bảng Nhiệm vụ sáng lên."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng. Ổ khóa rương có 3 vòng số, mỗi câu đúng xoay một vòng.","reward":"Búa đóng cọc + dây thừng.","vocab":["camp","tent","tool","box","open","camp map","counselor","backpack","gear"],"assets":["camp_sleeping_bag","camp_rope","river_sign","camp_bunting","river_tree_pine","hdri_dawn","mini_camp_hero","char_hiker_girl","ground_grass_platform","camp_gear_pile"],"subtitles":[{"en":"Arrive at camp! You open the first toolbox.","vi":"Đến trại! Em mở rương công cụ đầu tiên.","parts":["Đến ",["camp","trại",0],"! Em ",["open","mở",1]," rương công cụ đầu tiên."]},{"en":"The counselor hands you a map and a backpack.","vi":"Trưởng trại đưa em bản đồ và chiếc ba lô.","parts":[["Counselor","Trưởng trại",3]," đưa em bản đồ và chiếc ",["backpack","ba lô",2],"."]}]},{"n":2,"title":"Dựng lều 3 bước","minutes":5,"optional":false,"goal":"Đóng cọc, dựng khung, phủ bạt cho lều của đội.","beats":["Lều lên từng giai đoạn: cọc → khung → bạt.","Gió thổi mạnh nếu sai 3 câu liền: bạt bay nhẹ, phải giữ lại.","Cạnh lều bạt là một chiếc lều xanh lá của trại bạn để so sánh cách chằng."],"question_hook":"Dạng nối cặp (matching) hợp nhất: mỗi cặp đúng gắn một cọc vào đúng vị trí. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Lều hoàn chỉnh + túi ngủ.","vocab":["peg","pole","cover","hammer","strong","green tent","tent"],"assets":["camp_tent_stage","camp_sleeping_bag","camp_tarp","anim_kneel_work","camp_tent_green"],"subtitles":[{"en":"Drive the pegs into the ground with a hammer.","vi":"Đóng cọc xuống đất bằng búa.","parts":["Đóng ",["peg","cọc",3]," xuống đất bằng ",["hammer","búa",2],"."]},{"en":"Set the frame, then cover it with the tarp: the tent is really strong!","vi":"Dựng khung rồi phủ bạt: lều thật chắc!","parts":["Dựng khung rồi ",["cover","phủ",2]," bạt: lều thật ",["strong","chắc",1],"!"]}]},{"n":3,"title":"Củi khô và đá lửa","minutes":5,"optional":false,"goal":"Nhặt củi khô (tránh củi ướt), xếp bếp đá vòng và đánh lửa.","beats":["Củi ướt bốc khói xám, củi khô bén lửa ngay.","Đá lửa tóe tia sáng mỗi câu đúng; đủ 4 tia thì lửa bén.","Giá ba chân treo nồi trên vòng đá quanh bếp: dựng đúng ba chân thì nồi không nghiêng.","Bộ đánh lửa gồm thanh thép, đá lửa và mồi khô nằm trên bàn gỗ: gọi đúng tên từng món để được đánh lửa."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên từng bó củi.","reward":"Lửa trại + vỉ nướng.","vocab":["wood","dry","wet","fire","spark","tripod","stone circle","fire starter","flint"],"assets":["camp_firepit","river_firewood","river_woodpile","camp_matchbox","camp_axe","fx_fire","camp_tripod","ground_cobble_circle","camp_fire_starter"],"subtitles":[{"en":"Pick dry wood and avoid wet wood.","vi":"Nhặt củi khô, tránh củi ướt.","parts":["Nhặt ",["wood","củi",0]," ",["dry","khô",1],", tránh củi ",["wet","ướt",1],"."]},{"en":"Strike the flint: a small spark will become fire.","vi":"Đánh đá lửa: một tia lửa nhỏ sẽ thành lửa.","parts":["Đánh đá lửa: một ",["spark","tia lửa",2]," nhỏ sẽ thành ",["fire","lửa",0],"."]}]},{"n":4,"title":"Nướng xiên bữa tối","minutes":5,"optional":false,"goal":"Xiên thịt, cá, rau và nướng đến chín vàng.","beats":["Thanh độ chín: trả lời đúng để lật xiên đúng lúc.","Sai thì xiên hơi cháy cạnh, vẫn ăn được.","Xiên thịt và xiên rau chờ nướng: đọc đúng tên nguyên liệu trước khi xếp lên vỉ."],"question_hook":"Câu hỏi hiện trên xiên đang nướng; đúng = lật xiên đúng lúc. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Bữa tối (hồi năng lượng cả đội).","vocab":["grill","turn","cook","delicious","hungry","skewer","vegetable"],"assets":["camp_grill","camp_skewer","food_meat_raw","food_meat_cooked","food_fish_raw","food_fish_cooked","camp_table","anim_cook","camp_skewer_meat","camp_skewer_veg"],"subtitles":[{"en":"Put the meat and vegetables on the grill and remember to turn them.","vi":"Xiên thịt và rau lên vỉ nướng, đừng quên xoay.","parts":["Xiên thịt và rau lên ",["grill","vỉ nướng",2],", đừng quên ",["turn","xoay",2],"."]},{"en":"Everyone is hungry and every dish is delicious!","vi":"Ai cũng đói, món nào cũng ngon!","parts":["Ai cũng ",["hungry","đói",1],", món nào cũng ",["delicious","ngon",3],"!"]}]},{"n":5,"title":"Lọc nước hồ","minutes":5,"optional":false,"goal":"Lấy nước hồ, lọc qua sỏi, cát, than và đun sôi.","beats":["Bình lọc 3 tầng, mỗi câu đúng thêm một tầng.","Nước chuyển từ đục sang trong ngay trước mắt."],"question_hook":"Câu dạng sắp xếp (reorder) hợp: xếp đúng thứ tự các tầng lọc. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Nước sạch + cốc trại.","vocab":["filter","sand","boil","clean","drink"],"assets":["camp_water_filter","camp_bucket","camp_bottle_2","camp_bottle","river_pebbles"],"subtitles":[{"en":"Take lake water and filter it through sand.","vi":"Lấy nước hồ và lọc qua cát.","parts":["Lấy nước hồ và ",["filter","lọc",3]," qua ",["sand","cát",1],"."]},{"en":"Only after boiling is it clean water to drink.","vi":"Đun sôi xong mới thành nước sạch để uống.","parts":[["Boil","Đun sôi",3]," xong mới thành nước ",["clean","sạch",1]," để ",["drink","uống",1],"."]}]},{"n":6,"title":"Truy tìm túi xúc xích","minutes":5,"optional":false,"goal":"Đàn sóc tha mất túi xúc xích: lần theo dấu, lấy lại túi, hoàn thành bữa tối và lửa trại.","beats":["Dấu chân sóc dẫn qua bến gỗ, gốc cây, bụi dương xỉ.","Cuối chặng: lửa trại bùng lên hình lá cờ đội nhiều sao nhất."],"question_hook":"Mỗi điểm dấu chân có một câu hỏi; đúng thì sóc lộ ra. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Cờ đỉnh trại cho Đội Lều nhiều sao nhất.","vocab":["squirrel","follow","find","sausage"],"assets":["food_sausage","river_stump","river_dock","river_fern","camp_lantern","hdri_sunset"],"subtitles":[{"en":"The squirrels have taken the sausage bag!","vi":"Đàn sóc lấy mất túi xúc xích!","parts":["Đàn ",["squirrel","sóc",2]," lấy mất túi ",["sausage","xúc xích",2],"!"]},{"en":"Follow the footprints to find the bag again.","vi":"Lần theo dấu chân để tìm lại túi.","parts":[["Follow","Lần theo",1]," dấu chân để ",["find","tìm",1]," lại túi."]}]},{"n":7,"title":"Chặng phụ: Nướng kẹo dẻo","minutes":5,"optional":true,"goal":"Kéo dài: nướng kẹo dẻo, mỗi câu đúng kẹo phồng to hơn.","beats":["Kẹo vàng đều được 3 sao."],"question_hook":"Câu hỏi hiện ngay trên vật thể phát sáng như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["marshmallow","sweet","soft"],"assets":["camp_marshmallow_stick","camp_firepit"],"subtitles":[{"en":"Marshmallows are both sweet and soft.","vi":"Kẹo dẻo vừa ngọt vừa mềm.","parts":[["Marshmallow","Kẹo dẻo",3]," vừa ",["sweet","ngọt",1]," vừa ",["soft","mềm",2],"."]}]},{"n":8,"title":"Chặng phụ: Nhật ký trại","minutes":5,"optional":true,"goal":"Viết 3 câu nhật ký ngày đầu bằng tiếng Anh.","beats":["Nhật ký ghim lên bảng gỗ của trại."],"question_hook":"Câu viết ngắn, chấm theo tiêu chí, không tính thua.","reward":"Huy hiệu \"Trại Viên Ngày Đầu\".","vocab":["today","first","happy"],"assets":["camp_lantern","river_sign"],"subtitles":[{"en":"Today is the first day and I am very happy.","vi":"Hôm nay là ngày đầu tiên, em rất vui.","parts":["Hôm ",["today","nay",0]," là ngày ",["first","đầu tiên",1],", em rất ",["happy","vui",0],"."]}]}],{},["anim_cook","anim_kneel_work","camp_axe","camp_bottle","camp_bottle_2","camp_bucket","camp_bunting","camp_fire_starter","camp_firepit","camp_gear_pile","camp_grill","camp_lantern","camp_marshmallow_stick","camp_matchbox","camp_rope","camp_skewer","camp_skewer_meat","camp_skewer_veg","camp_sleeping_bag","camp_table","camp_tarp","camp_tent_green","camp_tent_stage","camp_tripod","camp_water_filter","char_hiker_girl","food_fish_cooked","food_fish_raw","food_meat_cooked","food_meat_raw","food_sausage","fx_fire","ground_cobble_circle","ground_grass_platform","hdri_dawn","hdri_sunset","mini_camp_hero","river_dock","river_fern","river_firewood","river_pebbles","river_sign","river_stump","river_tree_pine","river_woodpile"]],["camp-02",2,"Đại Hội Ẩm Thực Lửa Trại","Video bảng chế biến món ăn, chảo trên bếp đá + file: nướng thịt, bắt cá.","Trại tổ chức Đại hội Ẩm thực, và giám khảo năm nay là đầu bếp nổi tiếng Chef Marco ghé thăm. Mỗi Đội Lều nhận một thẻ công thức bằng tiếng Anh: cá nướng lá chuối, bắp nướng bơ, xiên thịt rau củ và bánh mì nướng. Nguyên liệu phải tự kiếm: bắt cá ở bến, hái rau ở vườn trại, đổi đồ với trại bên cạnh. Giữa chừng, lửa của ba bếp cùng tắt vì cơn gió lạ, cả trại phải cùng nhau nhóm lại. Cuối buổi, Chef Marco chấm điểm từng món, món nào được làm đúng công thức sẽ được đặt lên bàn tiệc lớn của trại.","Khu bếp chung ven sông, ba bếp đá vòng xếp hàng, bàn gỗ dài phủ khăn caro, đèn dây treo trên đầu. Buổi chiều nắng vàng, mùi khói gỗ thơm. Sau bếp là luống rau của trại và đất tơi mới xới. Chợ trại có xe lừa chở rau, bò sữa đứng gần, và giếng đá giữa sân.",[{"n":1,"title":"Thẻ công thức","minutes":5,"optional":false,"goal":"Nhận thẻ công thức, đọc nguyên liệu và các bước.","beats":["Chef Marco xuất hiện, chọn món cho từng đội.","Đọc đúng thẻ = mở danh sách nguyên liệu."],"question_hook":"Thẻ công thức hiện như tờ giấy cầm tay; câu đọc hiểu hợp nhất. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Danh sách nguyên liệu.","vocab":["recipe","ingredient","step","first"],"assets":["camp_table","camp_string_lights","river_sign"],"subtitles":[{"en":"Each recipe card lists the ingredients and every step.","vi":"Mỗi thẻ công thức có nguyên liệu và từng bước.","parts":["Mỗi thẻ ",["recipe","công thức",3]," có ",["ingredient","nguyên liệu",4]," và từng ",["step","bước",1],"."]},{"en":"First, get everything ready neatly.","vi":"Đầu tiên, chuẩn bị mọi thứ thật gọn gàng.","parts":[["First","Đầu tiên",1],", chuẩn bị mọi thứ thật gọn gàng."]}]},{"n":2,"title":"Đi chợ trại","minutes":5,"optional":false,"goal":"Bắt cá ở bến, hái rau, đổi bắp với trại bên.","beats":["Mỗi nguyên liệu là một câu hỏi tại chỗ.","Đổi đồ: trả lời đúng thì trại bên đồng ý đổi.","Hái rau ở luống của trại bỏ vào giỏ đan; mỗi loại rau đọc đúng tên mới được hái.","Xe lừa chở rau tới chợ trại, bò sữa đứng cạnh: đọc đúng tên hàng mới mua được."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Giỏ nguyên liệu đầy.","vocab":["fish","corn","vegetable","trade","basket","soil","cart","cow","market"],"assets":["food_fish_raw","food_corn","food_apple","river_dock","camp_bucket","ground_farmland","fish_basket","ground_soil_patch","village_cart","village_cow","ground_cobble_path_b"],"subtitles":[{"en":"At the camp market, you can catch fish or pick vegetables.","vi":"Ở chợ trại, em có thể bắt cá hay hái rau.","parts":["Ở chợ trại, em có thể bắt ",["fish","cá",0]," hay hái ",["vegetable","rau",2],"."]},{"en":"You trade corn with the next camp.","vi":"Em đổi bắp với trại bên cạnh.","parts":["Em ",["trade","đổi",3]," ",["corn","bắp",2]," với trại bên cạnh."]}]},{"n":3,"title":"Sơ chế","minutes":5,"optional":false,"goal":"Rửa, cắt, xiên nguyên liệu đúng thứ tự.","beats":["Dao chỉ cắt qua hoạt ảnh có găng tay.","Thứ tự sai thì Chef Marco nhắc nhẹ.","Giếng đá giữa sân dùng rửa rau: kéo gàu đúng số lần theo câu trả lời."],"question_hook":"Câu sắp xếp (reorder) để xếp các bước sơ chế. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Xiên sẵn sàng.","vocab":["wash","cut","slice","mix","well"],"assets":["camp_skewer","camp_table","food_meat_raw","camp_well"],"subtitles":[{"en":"Wash, cut, then skewer in the right order.","vi":"Rửa, cắt rồi xiên theo đúng thứ tự.","parts":[["Wash","Rửa",1],", ",["cut","cắt",1]," rồi xiên theo đúng thứ tự."]},{"en":"Slice thinly and mix well.","vi":"Thái mỏng và trộn đều.","parts":[["Slice","Thái",2]," mỏng và ",["mix","trộn",2]," ",["well","đều",2],"."]}]},{"n":4,"title":"Gió lạ thổi tắt lửa","minutes":5,"optional":false,"goal":"Cả trại cùng nhóm lại ba bếp đá.","beats":["Thanh lửa chung: mọi Đội Lều trả lời đúng đều làm lửa bùng thêm.","Củi khô ở kho, củi ướt ở bờ sông."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên từng bếp đá.","reward":"Ba bếp đỏ lửa.","vocab":["wind","together","relight","warm"],"assets":["camp_firepit","river_firewood","camp_matchbox","fx_fire","fx_smoke"],"subtitles":[{"en":"The wind blows out the fire! The whole camp relights it together.","vi":"Gió thổi tắt lửa! Cả trại cùng nhóm lại.","parts":["Gió thổi tắt lửa! Cả trại cùng ",["relight","nhóm lại",3],"."]},{"en":"The fire is warm again and everyone smiles.","vi":"Ngọn lửa ấm lại, ai cũng cười.","parts":["Ngọn lửa ",["warm","ấm",1]," lại, ai cũng cười."]}]},{"n":5,"title":"Nướng và lật","minutes":5,"optional":false,"goal":"Nướng đúng độ chín theo công thức.","beats":["Thanh độ chín cho mỗi món.","Đúng lúc lật = 3 sao.","Xiên cá nướng vàng và xiên rau: lật đúng lúc, đọc đúng tên món để Chef Marco chấm điểm.","Nồi trại bắc lên bếp để nấu súp: đọc đúng công thức thì nước sôi đều."],"question_hook":"Câu hỏi trên món đang nướng; đúng = lật đúng lúc. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Món chín vàng.","vocab":["grill","flip","golden","smell","grilled fish","turn over","pot","boil"],"assets":["camp_grill","camp_pan","food_fish_cooked","food_meat_cooked","food_corn","anim_cook","camp_skewer_fish","camp_skewer_veg","camp_pot"],"subtitles":[{"en":"Grill the fish until golden, and remember to flip it.","vi":"Nướng cá vàng ươm và nhớ lật mặt.","parts":[["Grill","Nướng",2]," cá vàng ươm và nhớ ",["flip","lật",3]," mặt."]},{"en":"The smell spreads through camp, and the fish is golden.","vi":"Mùi thơm bay khắp trại, cá đã vàng.","parts":["Mùi ",["smell","thơm",2]," bay khắp trại, cá đã ",["golden","vàng",2],"."]}]},{"n":6,"title":"Bàn tiệc của Chef Marco","minutes":5,"optional":false,"goal":"Trình bày món, Chef Marco chấm, bày lên bàn tiệc lớn.","beats":["Mỗi đội giới thiệu món bằng một câu tiếng Anh.","Bàn tiệc đầy món = Bảng Nhiệm vụ đầy.","Các đội ngồi quanh bàn tiệc của Chef Marco: ai đọc đúng món của mình thì được ngồi vào ghế.","Chef Marco rót nước cho cả bàn tiệc: câu đúng làm nước chảy đầy ly."],"question_hook":"Câu giới thiệu món (viết ngắn hoặc chọn câu đúng). Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Cúp Đầu Bếp Lửa Trại.","vocab":["taste","yummy","present","best","sit down","dinner table","pour","drink"],"assets":["camp_table","camp_bench","food_bread","camp_bottle_2","hdri_sunset","anim_sit_male","anim_sit_female","camp_coffee_splash"],"subtitles":[{"en":"Chef Marco tastes it: yummy!","vi":"Chef Marco nếm thử: ngon tuyệt!","parts":["Chef Marco ",["taste","nếm",2]," thử: ",["yummy","ngon tuyệt",3],"!"]},{"en":"This is the best dish on the table, so present it nicely.","vi":"Đây là món ngon nhất bàn tiệc, hãy bày thật đẹp.","parts":["Đây là món ",["best","ngon nhất",2]," bàn tiệc, hãy ",["present","bày",3]," thật đẹp."]}]},{"n":7,"title":"Chặng phụ: Món tráng miệng","minutes":5,"optional":true,"goal":"Kéo dài: nướng chuối và táo cho bàn tiệc.","beats":["Mỗi câu đúng thêm một phần tráng miệng."],"question_hook":"Câu hỏi hiện ngay trên vật thể phát sáng như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["dessert","banana","apple"],"assets":["food_apple","camp_grill"],"subtitles":[{"en":"Dessert: grill bananas and apples.","vi":"Tráng miệng: nướng chuối và táo.","parts":[["Dessert","Tráng miệng",3],": nướng ",["banana","chuối",1]," và ",["apple","táo",1],"."]}]},{"n":8,"title":"Chặng phụ: Viết thực đơn","minutes":5,"optional":true,"goal":"Viết thực đơn tiếng Anh cho bữa sáng mai.","beats":["Thực đơn được dán ở bếp trại."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng gỗ của trại. Câu viết, không tính thua.","reward":"Huy hiệu \"Đầu Bếp Nhí\".","vocab":["breakfast","menu","tomorrow"],"assets":["river_sign"],"subtitles":[{"en":"Write a menu for tomorrow's breakfast.","vi":"Viết thực đơn cho bữa sáng ngày mai.","parts":["Viết ",["menu","thực đơn",3]," cho bữa ",["breakfast","sáng",2]," ",["tomorrow","ngày mai",1],"."]}]}],{"note":"Mỗi Đội Lều nấu một món khác nhau để các đội không tranh cùng một bếp."},["anim_cook","anim_sit_female","anim_sit_male","camp_bench","camp_bottle_2","camp_bucket","camp_coffee_splash","camp_firepit","camp_grill","camp_matchbox","camp_pan","camp_pot","camp_skewer","camp_skewer_fish","camp_skewer_veg","camp_string_lights","camp_table","camp_well","fish_basket","food_apple","food_bread","food_corn","food_fish_cooked","food_fish_raw","food_meat_cooked","food_meat_raw","fx_fire","fx_smoke","ground_cobble_path_b","ground_farmland","ground_soil_patch","hdri_sunset","river_dock","river_firewood","river_sign","village_cart","village_cow"]],["camp-03",3,"Bão Nhỏ Ghé Trại","File: dựng lều, tìm củi, lọc nước; tình huống thời tiết thay đổi để tăng kịch tính.","Đài radio của trại báo một cơn bão nhỏ sẽ đi qua trong nửa giờ. Cô Trưởng trại Linh giao nhiệm vụ: chằng lều thật chắc, che bạt cho bếp, gom củi khô vào kho, đổ đầy nước sạch và treo đèn bão. Gió càng lúc càng mạnh, lều nào chưa chằng sẽ bị thổi nghiêng, củi ngoài trời sẽ ướt. Đúng lúc mưa to nhất, mất một ba lô của Bé Tôm, cả trại phải tìm trong mưa. Khi bão qua, cầu vồng hiện trên sông và cả trại quây quần bên lửa, kể lại cách mình đã giữ trại an toàn.","Trại bên sông giữa buổi chiều, mây xám kéo về từ đỉnh núi, gió làm cờ tam giác bay phần phật. Mưa lất phất rồi to dần, sau đó tạnh và có cầu vồng.",[{"n":1,"title":"Bản tin bão","minutes":5,"optional":false,"goal":"Nghe bản tin, lập kế hoạch giữ trại.","beats":["Radio phát bản tin tiếng Anh chậm.","Mỗi Đội Lều chọn 3 việc ưu tiên.","Bạn nhỏ áo cỏ chạy khắp trại báo tin bão: nghe đúng bản tin mới chuyển được tin."],"question_hook":"Câu nghe hiểu ngắn hợp nhất ở chặng này. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Kế hoạch giữ trại.","vocab":["storm","forecast","plan","safe"],"assets":["camp_lantern","camp_table","river_sign","hdri_cloudy","char_grass_kid"],"subtitles":[{"en":"The forecast says a storm is coming!","vi":"Bản tin dự báo: bão sắp đến!","parts":["Bản tin ",["forecast","dự báo",3],": ",["storm","bão",2]," sắp đến!"]},{"en":"The whole camp makes a plan to stay safe.","vi":"Cả trại lên kế hoạch để giữ an toàn.","parts":["Cả trại ",["plan","lên kế hoạch",2]," để giữ ",["safe","an toàn",1],"."]}]},{"n":2,"title":"Chằng lều","minutes":5,"optional":false,"goal":"Thêm cọc, căng dây gió, siết bạt.","beats":["Gió tăng mỗi phút; lều chưa chằng nghiêng dần.","Mỗi câu đúng thêm một dây gió.","Lều rách từ trận gió trước nằm cạnh lều mới để so sánh: nhìn chỗ nào hở thì chằng chỗ đó.","Một chiếc lều cũ đã rách tả tơi sau cơn gió: các đội đọc đúng từ để vá lại cho chắc."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên từng sợi dây gió.","reward":"Lều vững trong bão.","vocab":["tie","tight","strong","wind","torn tent","rope","torn","broken"],"assets":["camp_tent_stage","camp_rope","camp_tarp","anim_kneel_work","camp_tent_damaged","camp_tent_ruined_grey"],"subtitles":[{"en":"Tie the ropes tight so the tent stays strong against the wind.","vi":"Buộc dây thật chặt để lều vững trước gió.","parts":[["Tie","Buộc",1]," dây thật ",["tight","chặt",2]," để lều ",["strong","vững",1]," trước ",["wind","gió",1],"."]},{"en":"Tighten the cover and add rope to be sure.","vi":"Siết bạt và thêm dây cho chắc.","parts":["Siết bạt và thêm ",["rope","dây",1]," cho chắc."]}]},{"n":3,"title":"Che bếp, gom củi","minutes":5,"optional":false,"goal":"Căng bạt che bếp, mang củi khô vào kho trước mưa.","beats":["Củi để ngoài sẽ đổi màu sẫm (ướt).","Bạt căng giữa 2 cây thông."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Kho củi khô.","vocab":["cover","carry","inside","dry"],"assets":["camp_tarp","river_woodpile","river_firewood","river_shed"],"subtitles":[{"en":"Cover the stove and carry the dry wood inside.","vi":"Che bếp lại, mang củi khô vào kho.","parts":[["Cover","Che",2]," bếp lại, ",["carry","mang",2]," củi ",["dry","khô",1]," vào kho."]},{"en":"Wood kept inside will not get wet.","vi":"Củi để bên trong sẽ không bị ướt.","parts":["Củi để ",["inside","bên trong",2]," sẽ không bị ướt."]}]},{"n":4,"title":"Nước sạch và đèn bão","minutes":5,"optional":false,"goal":"Đổ đầy bình nước sạch, treo đèn bão quanh trại.","beats":["Đèn treo đủ = lối đi sáng khi trời tối sầm.","Nước lọc trước khi mưa làm hồ đục."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Đèn bão + nước dự trữ.","vocab":["lantern","light","fill","storm"],"assets":["camp_lantern","camp_water_filter","camp_bottle","camp_bucket"],"subtitles":[{"en":"Hang the storm lanterns to have light in the storm.","vi":"Treo đèn bão để có ánh sáng trong bão.","parts":["Treo đèn ",["lantern","bão",2]," để có ",["light","ánh sáng",1]," trong ",["storm","bão",2],"."]},{"en":"Fill the bottles with clean water before the heavy rain.","vi":"Đổ đầy bình nước sạch trước khi mưa to.","parts":[["Fill","Đổ đầy",2]," bình nước sạch trước khi mưa to."]}]},{"n":5,"title":"Tìm ba lô trong mưa","minutes":5,"optional":false,"goal":"Mưa to nhất: tìm ba lô của Bé Tôm theo các manh mối.","beats":["Manh mối: chiếc mũ, dấu chân, một con gấu bông.","Cả trại cùng tìm, mỗi đội một hướng."],"question_hook":"Mỗi manh mối là một câu hỏi; đúng thì manh mối tiếp theo sáng lên. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Ba lô tìm thấy.","vocab":["lost","search","where","found"],"assets":["camp_sleeping_bag","river_bush","river_stump","decal_footprint_mud"],"subtitles":[{"en":"Little Tom's backpack is lost! Let us search together.","vi":"Ba lô Bé Tôm bị lạc! Mình cùng tìm nhé.","parts":["Ba lô Bé Tôm bị ",["lost","lạc",2],"! Mình cùng ",["search","tìm",2]," nhé."]},{"en":"Where is the backpack? There it is: found!","vi":"Ba lô ở đâu nhỉ? Kia rồi, tìm thấy!","parts":["Ba lô ",["where","ở đâu",0]," nhỉ? Kia rồi, ",["found","tìm thấy",2],"!"]}]},{"n":6,"title":"Cầu vồng sau bão","minutes":5,"optional":false,"goal":"Bão qua: kiểm tra trại, nhóm lửa, kể chuyện.","beats":["Cầu vồng trên sông.","Bảng Nhiệm vụ đầy = trại đạt \"Trại An Toàn\"."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Danh hiệu \"Trại An Toàn\" + cờ cho Đội Lều giỏi nhất.","vocab":["rainbow","after","check","proud"],"assets":["camp_firepit","hdri_noon","anim_cheer"],"subtitles":[{"en":"The rain stops and a rainbow appears!","vi":"Mưa tạnh, cầu vồng hiện ra!","parts":["Mưa tạnh, ",["rainbow","cầu vồng",2]," hiện ra!"]},{"en":"The whole camp checks the tents and feels so proud.","vi":"Cả trại kiểm tra lều và thấy thật tự hào.","parts":["Cả trại ",["check","kiểm tra",1]," lều và thấy thật ",["proud","tự hào",2],"."]}]},{"n":7,"title":"Chặng phụ: Phơi đồ","minutes":5,"optional":true,"goal":"Kéo dài: phơi túi ngủ, giày ướt quanh lửa.","beats":["Mỗi câu đúng phơi khô một món."],"question_hook":"Câu hỏi hiện ngay trên vật thể phát sáng như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["wet","dry","hang"],"assets":["camp_sleeping_bag","camp_rope"],"subtitles":[{"en":"Hang the wet sleeping bags around the fire so they dry quickly.","vi":"Treo túi ngủ ướt quanh lửa cho mau khô.","parts":[["Hang","Treo",2]," túi ngủ ",["wet","ướt",1]," quanh lửa cho mau khô."]}]},{"n":8,"title":"Chặng phụ: Bản tin của em","minutes":5,"optional":true,"goal":"Mỗi đội đọc bản tin thời tiết ngày mai bằng tiếng Anh.","beats":["Bản tin hay nhất phát lại trên radio trại."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng gỗ của trại. Câu nói/viết ngắn, không tính thua.","reward":"Huy hiệu \"Người Giữ Trại\".","vocab":["sunny","cloudy","tomorrow"],"assets":["camp_lantern"],"subtitles":[{"en":"Will tomorrow be sunny or cloudy?","vi":"Ngày mai trời nắng hay nhiều mây?","parts":["Ngày ",["tomorrow","mai",1]," trời ",["sunny","nắng",2]," hay ",["cloudy","nhiều mây",2],"?"]}]}],{},["anim_cheer","anim_kneel_work","camp_bottle","camp_bucket","camp_firepit","camp_lantern","camp_rope","camp_sleeping_bag","camp_table","camp_tarp","camp_tent_damaged","camp_tent_ruined_grey","camp_tent_stage","camp_water_filter","char_grass_kid","decal_footprint_mud","hdri_cloudy","hdri_noon","river_bush","river_firewood","river_shed","river_sign","river_stump","river_woodpile"]],["camp-04",4,"Đêm Sao Và Lửa Trại Kể Chuyện","Video lều phát sáng ban đêm, lửa trại khói bốc; file: nhóm lửa trại.","Đêm thứ ba của trại là đêm Lửa Trại Lớn, và nhà thiên văn Dr. Stella mang kính thiên văn đến trại. Nhưng để lửa trại bùng lên, mỗi Đội Lều phải góp củi, treo đèn lồng và dựng ghế dài quanh bếp. Dr. Stella giấu bản đồ sao thành năm mảnh, mỗi mảnh nằm ở một góc trại và chỉ hiện ra khi đèn lồng sáng. Ghép đủ bản đồ, cả trại sẽ tìm được chòm sao Thuyền Câu và nghe câu chuyện cổ về nó. Đêm khép lại bằng món kẹo dẻo nướng và bài hát chung của trại.","Trại bên hồ về đêm, trời đầy sao, lều phát sáng ấm áp, đèn lồng treo dọc lối đi. Mặt hồ phản chiếu ánh trăng, tiếng dế kêu. Nhà trên cây treo đèn lồng, lối lát đá dẫn tới vòng ghế quanh lửa.",[{"n":1,"title":"Thắp đèn lồng","minutes":5,"optional":false,"goal":"Treo và thắp đèn lồng dọc lối đi.","beats":["Mỗi đèn sáng làm lộ một góc trại.","Lều phát sáng dần lên.","Đèn lồng được treo lên nhà trên cây: mỗi câu đúng thắp một ngọn.","Cây cổ thụ có đèn lồng treo trên cành: thắp sáng đèn là mở đầu đêm lửa trại."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên từng chiếc đèn lồng.","reward":"Lối đi sáng.","vocab":["lantern","light","dark","night","tree house","tree"],"assets":["camp_lantern","camp_string_lights","camp_tent_stage","hdri_night","tree_fort","camp_lantern_tree"],"subtitles":[{"en":"Light the lanterns along the path in the dark night.","vi":"Thắp đèn lồng dọc lối đi trong đêm tối.","parts":["Thắp ",["lantern","đèn lồng",2]," dọc lối đi trong đêm ",["dark","tối",1],"."]},{"en":"Each lantern lit makes the night less dark.","vi":"Mỗi ngọn đèn sáng lên làm đêm bớt tối.","parts":["Mỗi ngọn đèn sáng lên làm ",["night","đêm",0]," bớt tối."]}]},{"n":2,"title":"Góp củi lửa trại lớn","minutes":5,"optional":false,"goal":"Mỗi Đội Lều góp một bó củi cho bếp lớn.","beats":["Đống củi cao dần theo số câu đúng của cả trại."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Đống lửa trại lớn.","vocab":["wood","pile","big","share"],"assets":["river_woodpile","river_firewood","camp_firepit"],"subtitles":[{"en":"Each tent adds a bundle of wood to the big fire.","vi":"Mỗi lều góp một bó củi cho đống lửa lớn.","parts":["Mỗi lều góp một bó ",["wood","củi",0]," cho đống lửa lớn."]},{"en":"A big fire needs the whole camp to share the work.","vi":"Một đống lửa lớn cần cả trại cùng góp.","parts":["Một đống lửa ",["big","lớn",0]," cần cả trại ",["share","cùng góp",2],"."]}]},{"n":3,"title":"Ghế dài quanh lửa","minutes":5,"optional":false,"goal":"Khiêng ghế, xếp vòng tròn quanh bếp.","beats":["Ghế xếp đúng vòng = chỗ ngồi cho cả lớp.","Lối lát đá dẫn tới ghế dài: xếp ghế theo đúng thứ tự câu chuyện.","Cả lớp ngồi xuống ghế dài quanh lửa: mỗi câu đúng xếp thêm một chỗ ngồi."],"question_hook":"Câu nối cặp (matching) gắn ghế vào đúng chỗ. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Vòng ghế quanh lửa.","vocab":["bench","circle","sit","around","path","sit down"],"assets":["camp_bench","camp_chair","ground_cobble_path_a","anim_sit_male","anim_sit_female"],"subtitles":[{"en":"Carry the benches and place them in a circle.","vi":"Khiêng ghế dài xếp thành vòng tròn.","parts":["Khiêng ",["bench","ghế dài",3]," xếp thành ",["circle","vòng tròn",2],"."]},{"en":"Everyone sits down around the fire.","vi":"Mọi người ngồi xuống quanh bếp lửa.","parts":["Mọi người ",["sit","ngồi",1]," xuống ",["around","quanh",2]," bếp lửa."]}]},{"n":4,"title":"Năm mảnh bản đồ sao","minutes":5,"optional":false,"goal":"Tìm 5 mảnh bản đồ sao giấu ở các góc trại.","beats":["Mảnh chỉ hiện khi đèn gần đó đã sáng.","Mỗi mảnh = một câu hỏi."],"question_hook":"Câu đọc hiểu ngắn về sao và bầu trời. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Bản đồ sao hoàn chỉnh.","vocab":["star","map","piece","sky"],"assets":["surv_map","camp_lantern","river_stump"],"subtitles":[{"en":"Find the five pieces of the star map hidden around camp.","vi":"Tìm năm mảnh bản đồ sao giấu khắp trại.","parts":["Tìm năm ",["piece","mảnh",1]," bản đồ ",["star","sao",0]," giấu khắp trại."]},{"en":"This map points to tonight's sky.","vi":"Bản đồ này chỉ lên bầu trời đêm nay.","parts":["Bản đồ này chỉ lên ",["sky","bầu trời",1]," đêm nay."]}]},{"n":5,"title":"Chòm sao Thuyền Câu","minutes":5,"optional":false,"goal":"Ghép bản đồ, tìm chòm sao trên trời qua kính thiên văn.","beats":["Dr. Stella kể câu chuyện cổ về ông lão câu cá trên trời.","Câu đúng nối thêm một ngôi sao."],"question_hook":"Câu sắp xếp câu chuyện (reorder). Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Câu chuyện chòm sao.","vocab":["constellation","shine","story","telescope"],"assets":["hdri_night","camp_table"],"subtitles":[{"en":"Through the telescope you see the Fishing Boat constellation.","vi":"Qua kính thiên văn em thấy chòm sao Thuyền Câu.","parts":["Qua kính ",["telescope","thiên văn",3]," em thấy ",["constellation","chòm sao",4]," Thuyền Câu."]},{"en":"The stars shine together and tell a story.","vi":"Các ngôi sao cùng tỏa sáng và kể một câu chuyện.","parts":["Các ",["star","ngôi sao",0]," cùng ",["shine","tỏa sáng",2]," và kể một ",["story","câu chuyện",1],"."]}]},{"n":6,"title":"Lửa trại bùng lên","minutes":5,"optional":false,"goal":"Thắp lửa trại lớn, hát bài ca trại.","beats":["Lửa bùng lên cao, tia lửa bay lên trời sao.","Cờ Đội Lều giỏi nhất cắm cạnh lửa.","Cậu bé lang thang kể chuyện bên lửa: cả trại lặp lại câu cuối cho đúng."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Danh hiệu \"Đêm Sao Rực Rỡ\".","vocab":["campfire","sing","together","happy","storyteller"],"assets":["camp_firepit","fx_fire","fx_spark","anim_cheer","char_nomad_boy"],"subtitles":[{"en":"The campfire blazes and the whole camp sings together.","vi":"Lửa trại bùng lên, cả trại hát cùng nhau.","parts":[["Campfire","Lửa trại",3]," bùng lên, cả trại ",["sing","hát",1]," ",["together","cùng nhau",1],"."]},{"en":"Everyone is happy by the fire.","vi":"Ai cũng vui bên lửa.","parts":["Ai cũng ",["happy","vui",0]," bên lửa."]}]},{"n":7,"title":"Chặng phụ: Kẹo dẻo","minutes":5,"optional":true,"goal":"Kéo dài: nướng kẹo dẻo quanh lửa.","beats":["Kẹo phồng theo câu đúng."],"question_hook":"Câu hỏi hiện ngay trên vật thể phát sáng như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["marshmallow","toast"],"assets":["camp_marshmallow_stick"],"subtitles":[{"en":"Toast the marshmallows until lightly golden.","vi":"Nướng kẹo dẻo đến khi vàng nhẹ.","parts":[["Toast","Nướng",3]," ",["marshmallow","kẹo dẻo",3]," đến khi vàng nhẹ."]}]},{"n":8,"title":"Chặng phụ: Điều ước sao băng","minutes":5,"optional":true,"goal":"Viết một điều ước tiếng Anh.","beats":["Điều ước bay lên thành sao băng."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng gỗ của trại. Câu viết ngắn, không tính thua.","reward":"Huy hiệu \"Người Ngắm Sao\".","vocab":["wish","dream","future"],"assets":["hdri_night"],"subtitles":[{"en":"See a shooting star and wish for the future.","vi":"Thấy sao băng, hãy ước một điều cho tương lai.","parts":["Thấy sao băng, hãy ",["wish","ước",1]," một điều cho ",["future","tương lai",3],"."]}]}],{},["anim_cheer","anim_sit_female","anim_sit_male","camp_bench","camp_chair","camp_firepit","camp_lantern","camp_lantern_tree","camp_marshmallow_stick","camp_string_lights","camp_table","camp_tent_stage","char_nomad_boy","fx_fire","fx_spark","ground_cobble_path_a","hdri_night","river_firewood","river_stump","river_woodpile","surv_map","tree_fort"]],["camp-05",5,"Chuyến Dã Ngoại Thượng Nguồn","File: bối cảnh sông núi picnic, tìm thức ăn, lọc nước; video cầu gỗ ra hồ và rừng thông.","Cả trại khởi hành từ bến gỗ để lên bãi cắm trại mới ở thượng nguồn, nơi nghe nói có hồ nước trong nhất vùng. Hướng dẫn viên Leo đưa cho mỗi Đội Lều một bản đồ, một la bàn và một ba lô trống cần chuẩn bị đúng đồ. Trên đường, cầu gỗ cũ bị gãy một tấm ván, phải sửa mới qua được; rồi đến khúc sông cần lấy nước lọc để uống. Đến nơi, cả trại dựng lều mới, nhóm bếp, và nấu bữa trưa từ những gì hái được trên đường. Phần thưởng cuối cùng là chuyến chèo thuyền nhỏ ngắm hồ trên núi lúc hoàng hôn.","Đường mòn men theo sông lên thượng nguồn: cầu gỗ, rừng thông, thác nhỏ, và một bãi cỏ phẳng bên hồ trên núi. Trời trong, nắng nhẹ, mây trắng trôi chậm. Bản đồ nổi của thung lũng sông đặt trên bàn đá ở điểm xuất phát; trên đường có thác nhỏ đổ xuống hồ.",[{"n":1,"title":"Soạn ba lô","minutes":5,"optional":false,"goal":"Chọn đúng đồ cho chuyến đi (nước, áo mưa, đèn pin, hộp cứu thương).","beats":["Ba lô có giới hạn cân nặng: đồ thừa làm đi chậm.","Chị dẫn đường kiểm ba lô của từng bạn trước khi lên đường.","Cô hướng đạo kiểm tra danh sách đồ mang: nhận đúng tên từng món.","Gói lương khô cho chuyến đi: chỉ bỏ vào ba lô đúng số gói theo câu trả lời."],"question_hook":"Câu chọn đồ (trắc nghiệm, nối cặp đồ - công dụng). Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Ba lô chuẩn.","vocab":["pack","need","heavy","light","hiker","backpack","guide","map","food"],"assets":["camp_sleeping_bag","camp_firstaid","surv_flashlight","camp_bottle","river_dock","char_hiker_girl","char_female_a","camp_ration_pack"],"subtitles":[{"en":"Pack your backpack: bring only what you need.","vi":"Xếp ba lô: chỉ mang thứ em cần thôi.","parts":[["Pack","Xếp",1]," ba lô: chỉ mang thứ em ",["need","cần",1]," thôi."]},{"en":"The backpack should not be too heavy.","vi":"Ba lô không nên quá nặng.","parts":["Ba lô không nên quá ",["heavy","nặng",2],"."]}]},{"n":2,"title":"Bản đồ và la bàn","minutes":5,"optional":false,"goal":"Đọc bản đồ, chọn đúng ngã rẽ.","beats":["Ba ngã rẽ, mỗi ngã có biển chỉ đường.","Đi sai thì vòng lại 30 giây.","Bản đồ nổi của thung lũng: ghim đúng tên nơi cần đến, kim la bàn sẽ xoay theo."],"question_hook":"Câu hướng đi (north, left, across...). Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Đường tắt.","vocab":["map","compass","north","turn","relief map","valley"],"assets":["surv_map","surv_compass","river_sign","river_tree_pine","mini_ganga_valley"],"subtitles":[{"en":"Read the map and compass: the direction is north.","vi":"Đọc bản đồ và la bàn: hướng bắc.","parts":["Đọc ",["map","bản đồ",1]," và ",["compass","la bàn",3],": hướng ",["north","bắc",2],"."]},{"en":"At the fork, turn the right way.","vi":"Đến ngã ba, hãy rẽ đúng hướng.","parts":["Đến ngã ba, hãy ",["turn","rẽ",1]," đúng hướng."]}]},{"n":3,"title":"Sửa cầu gỗ","minutes":5,"optional":false,"goal":"Thay tấm ván gãy để cả trại qua suối.","beats":["Mỗi câu đúng đóng một đinh.","Cầu lắc nhẹ khi đông người."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên tấm ván.","reward":"Cầu qua suối.","vocab":["bridge","board","fix","cross"],"assets":["river_bridge","camp_axe","river_log_fallen"],"subtitles":[{"en":"The wooden bridge has a broken board.","vi":"Cầu gỗ gãy một tấm ván.","parts":[["Bridge","Cầu",1]," gỗ gãy một tấm ",["board","ván",2],"."]},{"en":"Once it is fixed, the whole camp crosses the stream safely.","vi":"Sửa xong, cả trại qua suối an toàn.","parts":[["Fix","Sửa",2]," xong, cả trại ",["cross","qua",2]," suối an toàn."]}]},{"n":4,"title":"Nước thượng nguồn","minutes":5,"optional":false,"goal":"Lấy nước sông, lọc và đun.","beats":["Nước thượng nguồn trong nhưng vẫn phải lọc.","Nước thượng nguồn chảy từ thác nhỏ: lọc xong mới được uống."],"question_hook":"Câu sắp xếp các bước lọc. Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Bình nước đầy.","vocab":["river","filter","boil","safe","waterfall","spring water"],"assets":["camp_water_filter","camp_bucket","river_rock_medium","river_waterfall_pool"],"subtitles":[{"en":"Take water from the river, then filter and boil it.","vi":"Lấy nước từ sông rồi lọc và đun sôi.","parts":["Lấy nước từ ",["river","sông",1]," rồi ",["filter","lọc",3]," và ",["boil","đun sôi",3],"."]},{"en":"Upstream water is safe after boiling.","vi":"Nước thượng nguồn thì an toàn sau khi đun.","parts":["Nước thượng nguồn thì ",["safe","an toàn",1]," sau khi đun."]}]},{"n":5,"title":"Dựng trại mới","minutes":5,"optional":false,"goal":"Dựng lều và bếp ở bãi cỏ bên hồ trên núi.","beats":["Lều 3 giai đoạn như ngày đầu nhưng nhanh hơn.","Hái nấm và quả an toàn (có biển nhận biết).","Lều lớn cho cả nhóm ở bãi mới: dựng đúng từng bước thì lều đứng vững."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Trại mới + bữa trưa.","vocab":["new","lake","pick","lunch","tent","shelter"],"assets":["camp_tent_stage","camp_firepit","camp_pan","food_apple","food_bread","camp_tent_family_grey"],"subtitles":[{"en":"Set up the new camp by the lake on the mountain.","vi":"Dựng trại mới bên hồ trên núi.","parts":["Dựng trại ",["new","mới",1]," bên ",["lake","hồ",1]," trên núi."]},{"en":"A great lunch by the lake.","vi":"Bữa trưa ngon tuyệt bên hồ.","parts":["Bữa ",["lunch","trưa",1]," ngon tuyệt bên hồ."]}]},{"n":6,"title":"Chèo thuyền hoàng hôn","minutes":5,"optional":false,"goal":"Chèo thuyền nhỏ ngắm hồ trên núi.","beats":["Mỗi câu đúng một nhịp chèo; cả đội chèo đồng đều thì thuyền đi thẳng.","Chuyến chèo thuyền hoàng hôn dùng thuyền chèo gỗ trắng của bến hồ."],"question_hook":"Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.","reward":"Danh hiệu \"Nhà Thám Hiểm Thượng Nguồn\".","vocab":["row","paddle","sunset","beautiful","rowboat"],"assets":["river_boat_row","river_dock","hdri_sunset","river_duck"],"subtitles":[{"en":"Row the little boat and watch the sunset.","vi":"Chèo thuyền nhỏ ngắm hoàng hôn.","parts":[["Row","Chèo",2]," thuyền nhỏ ngắm ",["sunset","hoàng hôn",2],"."]},{"en":"The view is so beautiful you forget your paddle.","vi":"Cảnh đẹp đến mức quên cả mái chèo.","parts":["Cảnh ",["beautiful","đẹp",1]," đến mức quên cả ",["paddle","mái chèo",1],"."]}]},{"n":7,"title":"Chặng phụ: Câu cá bên hồ","minutes":5,"optional":true,"goal":"Kéo dài: câu vài con cá cho bữa tối.","beats":["Mỗi câu đúng một lần giật cần."],"question_hook":"Câu hỏi hiện ngay trên vật thể phát sáng như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["fish","catch"],"assets":["fish_rod","fish_bobber"],"subtitles":[{"en":"Try to catch a few fish for dinner.","vi":"Cố bắt vài con cá cho bữa tối.","parts":["Cố ",["catch","bắt",1]," vài con ",["fish","cá",0]," cho bữa tối."]}]},{"n":8,"title":"Chặng phụ: Bưu thiếp","minutes":5,"optional":true,"goal":"Viết bưu thiếp tiếng Anh gửi gia đình.","beats":["Bưu thiếp có ảnh hồ trên núi."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm bảng gỗ của trại. Câu viết ngắn, không tính thua.","reward":"Huy hiệu \"Lữ Khách Nhí\".","vocab":["dear","miss you","see you"],"assets":["river_sign"],"subtitles":[{"en":"Dear Mom, I miss you, see you soon!","vi":"Gửi mẹ, con nhớ mẹ, hẹn gặp lại!","parts":[["Dear","Gửi",1]," mẹ, con ",["miss you","nhớ mẹ",2],", hẹn ",["see you","gặp lại",2],"!"]}]}],{"note":"Đường mòn chia 3 làn song song cho lớp đông; các Đội Lều xuất phát cách nhau 20 giây."},["camp_axe","camp_bottle","camp_bucket","camp_firepit","camp_firstaid","camp_pan","camp_ration_pack","camp_sleeping_bag","camp_tent_family